/** { method?, url, headers?, json? } ⇒ "curl -i …" */
function buildCurl(req) {
  // Write your solution here
  var cmd = 'curl -i -X ' + (req.method || 'GET');
  if (req.json) cmd += " --json '" + JSON.stringify(req.json) + "'";
  return cmd + ' ' + req.url;
}

